/**
 * S6 (PR #1707): Replace All must do what it says (F5).
 *
 * The server macro always wrote through; the defect was the surface:
 * the panel printed a success count even on refusal, and open editor
 * tabs were never reconciled, so the change was invisible in the
 * document and a stale buffer could overwrite it. These tests pin:
 *  - success reports the macro's real counts, marked as saved, and
 *    hands the changed paths to the caller's tab-reconciliation bridge;
 *  - the result list is regenerated by re-running the search;
 *  - a refusal renders as a failure with "Nothing was changed." and
 *    never triggers reconciliation.
 */
import React from 'react';
import { fireEvent, render, screen, waitFor } from '@testing-library/react';
import { beforeEach, describe, expect, it, vi } from 'vitest';

const lensRunMock = vi.fn();
vi.mock('@/lib/api/client', () => ({
  lensRun: (...args: unknown[]) => lensRunMock(...args),
}));

import { SearchPanel } from '@/components/code/SearchPanel';

type Call = { domain: string; action: string; input: Record<string, unknown> };
const calls = () => lensRunMock.mock.calls.map((c) => c[0] as Call);

beforeEach(() => { lensRunMock.mockReset(); });

function setup(replaceResult: unknown) {
  lensRunMock.mockImplementation((req: Call) => {
    if (req.action === 'search-project') {
      return Promise.resolve({ data: { ok: true, result: { hits: [{ file: 'a.ts', line: 1, column: 1, preview: 'const x = OLD;' }] } } });
    }
    if (req.action === 'replace-project') return Promise.resolve({ data: replaceResult });
    return Promise.resolve({ data: { ok: true, result: {} } });
  });
  const onReplaced = vi.fn();
  render(<SearchPanel projectId="p1" onOpen={() => undefined} onReplaced={onReplaced} />);
  return onReplaced;
}

async function driveReplace() {
  fireEvent.change(screen.getByPlaceholderText('Search text…'), { target: { value: 'OLD' } });
  fireEvent.click(screen.getByTitle('Toggle replace'));
  fireEvent.change(await screen.findByPlaceholderText('Replace with…'), { target: { value: 'NEW' } });
  fireEvent.click(screen.getByTitle('Replace all'));
}

describe('SearchPanel Replace All (S6)', () => {
  it('reports the real count as saved and hands changed paths to the bridge', async () => {
    const onReplaced = setup({ ok: true, result: { changed: [{ path: 'a.ts', replacements: 2 }], filesChanged: 1, totalReplacements: 2 } });
    await driveReplace();
    expect(await screen.findByText('Replaced 2 occurrence(s) across 1 file(s) — saved.')).toBeTruthy();
    expect(onReplaced).toHaveBeenCalledWith(['a.ts']);
    // Results regenerate from the post-replace documents (search re-runs).
    await waitFor(() => expect(calls().filter((c) => c.action === 'search-project').length).toBeGreaterThanOrEqual(1));
    const rep = calls().find((c) => c.action === 'replace-project');
    expect(rep?.input).toMatchObject({ projectId: 'p1', query: 'OLD', replacement: 'NEW' });
  });

  it('a refusal renders as a failure — no count, no reconciliation', async () => {
    const onReplaced = setup({ ok: false, error: 'invalid regex: (' });
    await driveReplace();
    expect(await screen.findByText(/Replace failed: invalid regex[\s\S]*Nothing was changed\./)).toBeTruthy();
    expect(onReplaced).not.toHaveBeenCalled();
    expect(screen.queryByText(/Replaced \d+ occurrence/)).toBeNull();
  });
});
